INSERT OR IGNORE INTO news (
  slug, title, category, published_date, source_name, source_url,
  summary, body, image_url, image_credit, image_source, verification_json, source
) VALUES (
  'taxi-violence-matric-english-exam-candidates-redirected-2026-10-28',
  'Taxi unrest forces matric candidates to nearest exam centres',
  'Community', '2026-10-28', 'Cape Town Etc', 'https://www.capetownetc.com/news/cape-town-taxi-violence-disrupts-travel-for-matric-exam-candidates/',
  'Taxi violence in several Cape Town areas disrupted transport on the morning of the matric English paper, and the education department allowed late and redirected candidates.',
  'Taxi and gang-related violence in areas including Delft, Khayelitsha and Nyanga disrupted travel on Wednesday morning, while thousands of matric candidates were writing the National Senior Certificate English examination.

The Western Cape Education Department says it learnt of the unrest through its security networks and alerted examination centres across the metro. Provincial Education Minister Jaco Londt told officials to watch candidate arrivals closely and to contact learners who had not turned up.

According to the department, a candidate who could not reach their registered centre because of safety or transport problems may report to the nearest centre as an emergency alternative. Candidates held up by circumstances beyond their control may arrive up to an hour after the paper has started and still be admitted. Londt said everyone who reached their centres was able to write.

Candidates are advised to leave home earlier than usual if transport disruptions are reported, and to contact their school as soon as possible if they cannot get to their centre. TimesLIVE reports that the Delft public transport interchange was temporarily closed as rival taxi associations clashed. The department says it will keep monitoring the situation.',
  NULL, NULL, NULL,
  '["https://www.capetownetc.com/news/cape-town-taxi-violence-disrupts-travel-for-matric-exam-candidates/", "https://www.timeslive.co.za/news/south-africa/2026-10-28-cape-town-taxi-violence-disrupts-matric-exams-as-candidates-diverted-to-alternative-centres/"]',
  'agent'
);
INSERT OR IGNORE INTO news (
  slug, title, category, published_date, source_name, source_url,
  summary, body, image_url, image_credit, image_source, verification_json, source
) VALUES (
  'fake-e-hailing-drivers-cape-town-airport-card-machine-warning-2026-10-28',
  'Visitors warned of fake e-hailing drivers at Cape Town airport',
  'Tourism', '2026-10-28', 'Cape Town Etc', 'https://www.capetownetc.com/news/tourists-warned-about-fake-e-hailing-charging-up-to-r25-000-at-cape-town-airport/',
  'Travellers arriving at Cape Town International Airport are being warned about fake e-hailing drivers who allegedly inflate card payments to as much as R25 000.',
  'A fresh warning is circulating about fake e-hailing drivers who approach arriving passengers at Cape Town International Airport. The claims come from a contractor working at the airport who also drives part-time for e-hailing services, as reported by MyBroadband and repeated by Getaway and Cape Town Etc.

The scam is said to start near the exits, where people in reflective vests and carrying fake identity cards give wrong directions to the official pickup points and persuade travellers to cancel their app bookings. At the end of the trip, a card machine is allegedly used to charge far more than the fare. The contractor described a R250 fare being entered as R25 000.

Reported cases include a British visitor aged 70 who was allegedly billed 800 pounds, roughly R17 690, and another passenger allegedly asked for R10 000 for a trip that should cost about R200. All of these accounts are allegations. Airports Company South Africa has put up warning signs, but the contractor says some have been removed.

Travellers are advised to book through an official e-hailing app and follow its pickup instructions, to ignore unsolicited offers, and to check the driver and vehicle registration against the booking. Passengers should confirm the amount on a card terminal before tapping, and ask airport staff for help if a driver changes the fare or the payment method.',
  NULL, NULL, NULL,
  '["https://www.capetownetc.com/news/tourists-warned-about-fake-e-hailing-charging-up-to-r25-000-at-cape-town-airport/", "https://mybroadband.co.za/news/motoring/674176-r25000-to-take-a-fake-uber-from-a-major-airport-in-south-africa.html", "https://www.getaway.co.za/travel-news/tourists-warned-about-fake-uber-drivers-charging-up-to-r25000-at-cape-town-airport/"]',
  'agent'
);
